import { useEffect, useState, useCallback, useMemo } from 'react';
import { useSendbirdStateContext } from '@sendbird/uikit-react';
import { BaseChannel } from '@sendbird/chat';

import { PushPin } from '@phosphor-icons/react';
import {
    GroupChannelListOrder,
    GroupChannel,
    SendbirdGroupChat,
    GroupChannelSearchField,
    GroupChannelHandler
} from '@sendbird/chat/groupChannel';
import { useGetSettings, usePatchSettings } from 'called-api/src/openApi/calledApiComponents';
import { useResponsive } from 'called-common/src/hooks/useResponsive';
import { log } from 'called-common/src/utils/logger';
import { useDebounce } from 'use-debounce';
import { useParams } from 'wouter';
import { calledChatRoutes } from '@/utils/route';
import { useTransitionLocation } from '@/hooks/useTransitionLocation';
import { useGlobalSearchStore } from '@/stores/GlobalSearchState';
import { useChannelListStore } from '@/stores/ChannelListState';
import { useLastVisitedChannelStore } from '@/stores/LastVisitedChannelStore';
import { ChannelFilter, filterChannels, getChannelName, getEmptyFilterMessage, isCustomerSuccessChannel } from '@/utils/channel';
import { usePullToRefreshAddHandler } from '@/hooks/usePullToRefreshAddHandler';
import { useIsCustomerSuccessStaff } from '@/hooks/useIsCustomerSuccessStaff';
import { useSendbirdConnectionStore } from '@/stores/SendbirdConnectionState';
import { ChannelList } from './ChannelList';
import { CalledTeamSection } from './CalledTeamSection';
import { ContactListLoading } from './ContactListLoading';
import { ContactHeader } from './ContactHeader';
import { dismissInboxFilterSelection } from './InboxConversation/inboxThreadUtils';
import { NewsInbox } from './NewsInbox/NewsInbox';
import { PrayersInbox } from './PrayersInbox/PrayersInbox';
import './ContactList.scss';

const REFRESH_INTERVAL = 5000;
const TOP_CHANNELS_LIMIT = 50;

export const ContactList = () => { … };

