39:export const ContactList = () => {
40:    const [channelList, setChannelList] = useState<GroupChannel[]>([]);
41:    const [listLoading, setListLoading] = useState(true);
42:    const { channelUrl } = useParams();
43:    const sendbirdState = useSendbirdStateContext();
44:    const sb = sendbirdState.stores.sdkStore.sdk as SendbirdGroupChat;
45:    const [, setLocation] = useTransitionLocation();
46:    const [searchTerm, setSearchTerm] = useState('');
47:    const [debouncedSearchTerm] = useDebounce(searchTerm, 300);
48:    const [pinnedChannels, setPinnedChannels] = useState<string[]>([]);
49:    const { data: profileSettings } = useGetSettings({});
50:    const [isInitialized, setIsInitialized] = useState(false);
51:    const { mutate: patchSettings } = usePatchSettings();
52:    const { isMobile } = useResponsive();
53:    const [activeFilter, setActiveFilter] = useState<ChannelFilter>('all');
54:    const isCustomerSuccessStaff = useIsCustomerSuccessStaff();
55:
56:    const handleFilterChange = useCallback((filter: ChannelFilter) => {
57:        if (filter !== activeFilter) {
58:            dismissInboxFilterSelection();
59:        }
60:
61:        setActiveFilter(filter);
62:    }, [activeFilter]);
63:
64:    const sortChannels = (channels: GroupChannel[], pinnedChannelsToSort: string[]) => {
65:        const pinnedChans = channels.filter(ch => pinnedChannelsToSort.includes(ch.url));
66:        const unpinnedChans = channels.filter(ch => !pinnedChannelsToSort.includes(ch.url));
67:
68:        const sortedPinned = [...pinnedChans].sort((a, b) => {
69:            const aIndex = pinnedChannelsToSort.indexOf(a.url);
70:            const bIndex = pinnedChannelsToSort.indexOf(b.url);
71:            return aIndex - bIndex;
72:        });
73:
74:        const sortedUnpinned = [...unpinnedChans].sort((a, b) => {
75:            const aTime = a.lastMessage?.createdAt || 0;
76:            const bTime = b.lastMessage?.createdAt || 0;
77:            return bTime - aTime;
78:        });
79:
80:        return [...sortedPinned, ...sortedUnpinned];
81:    };
82:
83:    useEffect(() => {
84:        if (sb.groupChannel && profileSettings) {
85:            // Set pinned channels first
86:            if (profileSettings.pinnedChannels) {
87:                const sortedChannels = [...profileSettings.pinnedChannels]
88:                    .sort((a, b) => a.order - b.order)
89:                    .map(pin => pin.channel);
90:                setPinnedChannels(sortedChannels);
91:            }
92:
93:            setIsInitialized(true);
94:        }
95:    }, [profileSettings?.pinnedChannels, sb.groupChannel]);
96:
97:    // Handle pinned channels changes
98:    useEffect(() => {
99:        // We check if initialized since we're getting pinned from our backend, and all the channels from sendbird, just want to reduce any race conditions
100:        // This also fires when we pin or unpin after load.
101:        if (isInitialized) {
102:            // Rearrange the current channel list to respect new pinned order
103:            setChannelList(prevChannels => {
104:                const sortedChannels = sortChannels(prevChannels, pinnedChannels);
105:                return sortedChannels;
106:            });
107:        }
108:    }, [pinnedChannels, isInitialized]);
109:
110:    // This gets the top X channels and updates the list, this is mainly used for user activity
111:    // This is called on a timer, this is in order to update user status, etc.
112:    const refreshRecentChannels = useCallback(async () => {
113:        // If we're searching, don't refresh since it would override the search.
114:        if (!sb.groupChannel || debouncedSearchTerm !== '') {
115:            return;
116:        }
117:
118:        try {
119:            const query = sb.groupChannel.createMyGroupChannelListQuery({
120:                limit: TOP_CHANNELS_LIMIT,
121:                includeEmpty: false,
122:                order: GroupChannelListOrder.LATEST_LAST_MESSAGE
123:            });
124:
125:            const recentChannels = await query.next();
126:
127:            // Update existing channels preserving pinned order
128:            setChannelList(prevChannels => {
129:                const recentChannelMap = new Map(recentChannels.map(ch => [ch.url, ch]));
130:
131:                // First, update all existing channels with new data
132:                const updatedChannels = prevChannels.map(channel =>
133:                    recentChannelMap.get(channel.url) || channel
134:                );
135:
136:                // Add any new channels that weren't in our list
137:                recentChannels.forEach(channel => {
138:                    if (!updatedChannels.some(ch => ch.url === channel.url)) {
139:                        updatedChannels.push(channel);
140:                    }
141:                });
142:
143:                return sortChannels(updatedChannels, pinnedChannels);
144:            });
145:        } catch (error) {
146:            log.error('Error refreshing recent channels', error);
147:        }
148:    }, [sb.groupChannel, pinnedChannels, debouncedSearchTerm]);
149:
150:    // This gets all the channels from sendbird, this is used for the initial load and the search.
151:    const getChannels = async (searchKeyword = '') => {
152:        if (!sb.groupChannel) {
153:            return [];
154:        }
155:
156:        try {
157:            const query = sb.groupChannel.createMyGroupChannelListQuery({
158:                limit: 100, // 100 is the max limit for sendbird
159:                includeEmpty: true,
160:                order: GroupChannelListOrder.LATEST_LAST_MESSAGE,
161:                ...(searchKeyword && {
162:                    searchFilter: {
163:                        query: searchKeyword,
164:                        fields: [GroupChannelSearchField.CHANNEL_NAME, GroupChannelSearchField.MEMBER_NICKNAME],
165:                    }
166:                })
167:            });
168:
169:            // Get all channels in one go
170:            const channels: GroupChannel[] = [];
171:            while (query.hasNext) {
172:                // eslint-disable-next-line no-await-in-loop
173:                const batch = await query.next();
174:                channels.push(...batch);
175:            }
176:
177:            return channels;
178:        } catch (error) {
179:            log.error('Error fetching channels', error);
180:            return [];
181:        }
182:    };
183:
184:    // CS channels never appear in the main list. Non-staff see them via
185:    // <CalledTeamSection> pinned above; staff reach them via the Customer
186:    // Support filter row.
187:    const mainChannelList = useMemo(
188:        () => channelList.filter(ch => !isCustomerSuccessChannel(ch)),
189:        [channelList]
190:    );
191:
192:    // This selects the first channel in the list, used when we don't have a channelUrl.
193:    // Uses mainChannelList so staff don't auto-land in (and instantly read) the CS
194:    // channel — it's reachable only via the Customer Support filter. Non-staff
195:    // customers with only a CS channel still land there so they're not left
196:    // with no selection.
197:    const selectFirstChannel = () => {
198:        const firstChannel = mainChannelList[0]
199:            ?? (!isCustomerSuccessStaff ? channelList.find(ch => isCustomerSuccessChannel(ch)) : undefined);
200:        if (firstChannel) {
201:            setLocation(`/${calledChatRoutes.chat.route}/${firstChannel.url}`);
202:        }
203:    };
204:
205:    async function fetchInitialData() {
206:        if (!isInitialized || !sb.groupChannel) {
207:            return;
208:        }
209:
210:        setListLoading(true);
211:        try {
212:            const allChannels = await getChannels();
213:            const sortedChannels = sortChannels(allChannels, pinnedChannels);
214:            setChannelList(sortedChannels);
215:        } catch (error) {
216:            log.error('Error fetching initial channels', error);
217:        } finally {
218:            setListLoading(false);
219:        }
220:         
221:    }
222:
223:    const refreshSendbird = useSendbirdConnectionStore((state) => state.refreshSendbird);
224:
225:    usePullToRefreshAddHandler(refreshSendbird);
226:
227:    // When there's no channelUrl, land on the first channel. Keyed on channelUrl
228:    // and channelList as well as listLoading so navigating to bare /chat, or a
229:    // list that populates on a later refresh, still selects a channel instead of
230:    // leaving the list mounted with nothing open. We wait for listLoading so a
231:    // re-fetch (e.g. reconnect) doesn't pick from a stale, retained list.
232:    useEffect(() => {
233:        if (!channelUrl && !listLoading) {
234:            selectFirstChannel();
235:        }
236:    }, [channelUrl, listLoading, channelList]);
237:
238:    // Fetch once initialized
239:    useEffect(() => {
240:        if (isInitialized) {
241:            void fetchInitialData();
242:        }
243:    }, [isInitialized]);
244:
245:    const removeChannelFromPinned = useCallback((channelToRemove: string) => {
246:        // Remove from local state
247:        setPinnedChannels(prev => prev.filter(url => url !== channelToRemove));
248:
249:        // Update server settings
250:        void patchSettings({
251:            body: {
252:                pinnedChannels: profileSettings?.pinnedChannels?.filter(
253:                    pinnedChannel => pinnedChannel.channel !== channelToRemove
254:                ) || [],
255:            },
256:        });
257:    }, [profileSettings?.pinnedChannels, patchSettings]);
258:
259:    useEffect(() => {
260:        if (!sb.groupChannel) {
261:            return () => {};
262:        }
263:
264:        // Setup channel handler for real-time updates, this is called from the handlers below.
265:        const updateChannelList = (baseChannel: BaseChannel) => {
266:            const channel = baseChannel as GroupChannel;
267:            setChannelList(prevChannels => {
268:                // First update/add the changed channel
269:                const updatedChannels = prevChannels.map(ch =>
270:                    ch.url === channel.url ? channel : ch
271:                );
272:
273:                // If channel wasn't in the list, add it
274:                if (!updatedChannels.some(ch => ch.url === channel.url)) {
275:                    updatedChannels.push(channel);
276:                }
277:
278:                return sortChannels(updatedChannels, pinnedChannels);
279:            });
280:        };
281:
282:        const channelHandler = new GroupChannelHandler({
283:            onMessageReceived: (channel) => {
284:                updateChannelList(channel);
285:            },
286:            onMessageUpdated: (channel) => {
287:                updateChannelList(channel);
288:            },
289:            onUnreadMemberStatusUpdated: (channel) => {
290:                updateChannelList(channel);
291:            },
292:            onChannelChanged: (channel) => {
293:                updateChannelList(channel);
294:            },
295:            onChannelDeleted: (deletedChannelUrl) => {
296:                // Remove from channel list
297:                setChannelList(prevChannels =>
298:                    prevChannels.filter(ch => ch.url !== deletedChannelUrl)
299:                );
300:
301:                if (pinnedChannels.includes(deletedChannelUrl)) {
302:                    removeChannelFromPinned(deletedChannelUrl);
303:                }
304:
305:                void refreshRecentChannels();
306:            },
307:            onUserJoined: (baseChannel, user) => {
308:                const channel = baseChannel as GroupChannel;
309:                if (user.userId === sb.currentUser?.userId) {
310:                    setChannelList(prevChannels => {
311:                        // Check if this channel already existed in our list
312:                        const joinChannelExists = prevChannels.some(ch => ch.url === channel.url);
313:
314:                        if (!joinChannelExists) {
315:                            // Only reorder for new channels
316:                            const lastPinnedIndex = pinnedChannels.length > 0
317:                                ? prevChannels.findIndex(ch => ch.url === pinnedChannels[pinnedChannels.length - 1])
318:                                : -1;
319:
320:                            return [
321:                                ...prevChannels.slice(0, lastPinnedIndex + 1),
322:                                channel,
323:                                ...prevChannels.slice(lastPinnedIndex + 1)
324:                            ];
325:                        }
326:
327:                        // For existing channels, just update the channel data in place
328:                        return prevChannels.map(ch =>
329:                            ch.url === channel.url ? channel : ch
330:                        );
331:                    });
332:                }
333:                // refresh the recent channels
334:                void refreshRecentChannels();
335:            },
336:            onUserLeft: (baseChannel, user) => {
337:                const channel = baseChannel as GroupChannel;
338:
339:                // onUserLeft fires for EVERY remaining member when anyone leaves, so
340:                // only touch our own list/pins/selection when WE are the one who left.
341:                // Otherwise one member leaving would unpin the channel for everyone else.
342:                if (user.userId === sb.currentUser?.userId) {
343:                    setChannelList(prevChannels =>
344:                        prevChannels.filter(ch => ch.url !== channel.url)
345:                    );
346:
347:                    if (pinnedChannels.includes(channel.url)) {
348:                        removeChannelFromPinned(channel.url);
349:                    }
350:
351:                    // If we left the channel and had it selected, select the first channel
352:                    if (channel.url === channelUrl) {
353:                        selectFirstChannel();
354:                    }
355:                }
356:
357:                void refreshRecentChannels();
358:            },
359:
360:        });
361:
362:        sb.groupChannel.addGroupChannelHandler('ContactListHandler', channelHandler);
363:
364:        return () => {
365:            sb.groupChannel.removeGroupChannelHandler('ContactListHandler');
366:        };
367:    }, [sb.groupChannel, pinnedChannels]);
368:
369:    // If the URL points at a channel that isn't in our local list yet
370:    // (e.g. just-created DM where the Sendbird onUserJoined event hasn't
371:    // landed), fetch it directly from Sendbird and add it instead of
372:    // bouncing the user to the first channel.
373:    useEffect(() => {
374:        if (!channelUrl || channelUrl.includes('new') || listLoading) {
375:            return undefined;
376:        }
377:
378:        if (channelList.some(channel => channel.url === channelUrl)) {
379:            return undefined;
380:        }
381:
382:        let cancelled = false;
383:
384:        void (async () => {
385:            try {
386:                const channel = await sb.groupChannel.getChannel(channelUrl);
387:                if (cancelled || !channel || channel.url !== channelUrl) {
388:                    return;
389:                }
390:                setChannelList(prev => {
391:                    if (prev.some(ch => ch.url === channel.url)) {
392:                        return prev;
393:                    }
394:                    return sortChannels([...prev, channel], pinnedChannels);
395:                });
396:            } catch {
397:                if (!cancelled) {
398:                    // The remembered channel no longer resolves (deleted, or the
399:                    // user left it), so forget it before falling back — otherwise
400:                    // Chat would keep aiming at the dead url on every visit.
401:                    const { lastVisitedChannelUrl, setLastVisitedChannelUrl } = useLastVisitedChannelStore.getState();
402:                    if (channelUrl === lastVisitedChannelUrl) {
403:                        setLastVisitedChannelUrl(null);
404:                    }
405:                    selectFirstChannel();
406:                }
407:            }
408:        })();
409:
410:        return () => {
411:            cancelled = true;
412:        };
413:    }, [channelUrl, channelList, listLoading]);
414:
415:    // Remember the last channel the user actually landed on so the "Chat" nav
416:    // button can bring them back here. We only persist a channel that's in the
417:    // list, which guarantees it's real and viewable (DMs included) and excludes
418:    // placeholders like 'undefined'/'new' or channels the user has left. Read
419:    // via getState() so writing doesn't re-render this list on every refresh.
420:    useEffect(() => {
421:        if (!channelUrl || !channelList.some(channel => channel.url === channelUrl)) {
422:            return;
423:        }
424:
425:        const { lastVisitedChannelUrl, setLastVisitedChannelUrl } = useLastVisitedChannelStore.getState();
426:        if (channelUrl !== lastVisitedChannelUrl) {
427:            setLastVisitedChannelUrl(channelUrl);
428:        }
429:    }, [channelUrl, channelList]);
430:
431:    const handleSearch = (term: string) => {
432:        setSearchTerm(term);
433:    };
434:
435:    // Refresh channels at an interval, this is used to update the unread count and other things
436:    useEffect(() => {
437:        void refreshRecentChannels();
438:        const intervalId = setInterval(() => {
439:            void refreshRecentChannels();
440:        }, REFRESH_INTERVAL);
441:
442:        return () => clearInterval(intervalId);
443:    }, [refreshRecentChannels]);
444:
445:    const customerSupportUnreadCount = useMemo(
446:        () => channelList
447:            .filter((ch) => isCustomerSuccessChannel(ch))
448:            .reduce((sum, ch) => sum + ch.unreadMessageCount, 0),
449:        [channelList]
450:    );
451:
452:    // Staff only see the Customer Support filter when they're actually a member
453:    // of at least one CS channel. Domain alone isn't enough — most @called.app
454:    // accounts aren't on any CS channel and shouldn't see the row.
455:    const hasCustomerSupportChannels = useMemo(
456:        () => channelList.some((ch) => isCustomerSuccessChannel(ch)),
457:        [channelList]
458:    );
459:
460:    const customerSuccessChannels = useMemo(
461:        () => (isCustomerSuccessStaff ? [] : channelList.filter(ch => isCustomerSuccessChannel(ch))),
462:        [channelList, isCustomerSuccessStaff]
463:    );
464:
465:    // CS unread is counted toward the main Unread badge for customers (since
466:    // they see the Called Team section inline with their list), and excluded
467:    // for staff (who have a dedicated Customer Support filter with its own count).
468:    const totalUnreadCount = useMemo(() => {
469:        const mainCount = mainChannelList.reduce((sum, ch) => sum + ch.unreadMessageCount, 0);
470:        return isCustomerSuccessStaff ? mainCount : mainCount + customerSupportUnreadCount;
471:    }, [mainChannelList, customerSupportUnreadCount, isCustomerSuccessStaff]);
472:
473:    const filteredChannelList = useMemo(
474:        () => (activeFilter === 'customer_support'
475:            ? filterChannels(channelList, 'customer_support')
476:            : filterChannels(mainChannelList, activeFilter)),
477:        [channelList, mainChannelList, activeFilter]
478:    );
479:
480:    const setSharedChannelList = useChannelListStore((state) => state.setChannelList);
481:    useEffect(() => {
482:        setSharedChannelList(channelList);
483:    }, [channelList, setSharedChannelList]);
484:
485:    const currentUserId = sb.currentUser?.userId ?? '';
486:    const searchFilteredChannels = useMemo(() => {
487:        if (!searchTerm) {
488:            return filteredChannelList;
489:        }
490:        const lowerTerm = searchTerm.toLowerCase();
491:        return filteredChannelList.filter((channel) =>
492:            getChannelName(channel, currentUserId).toLowerCase().includes(lowerTerm)
493:        );
494:    }, [filteredChannelList, searchTerm, currentUserId]);
495:
496:    const filteredPinnedChannels = useMemo(
497:        () => pinnedChannels.filter(url => searchFilteredChannels.some(ch => ch.url === url)),
498:        [pinnedChannels, searchFilteredChannels]
499:    );
500:
501:    const { searchTerm: globalSearchTerm, isSearchActive: isGlobalSearchActive } = useGlobalSearchStore((state) => ({
502:        searchTerm: state.searchTerm,
503:        isSearchActive: state.isSearchActive,
504:    }));
505:
506:    // Sync local input when global store is cleared (e.g. clicking a search result)
507:    useEffect(() => {
508:        if (globalSearchTerm === '' && searchTerm !== '') {
509:            setSearchTerm('');
510:        }
511:    }, [globalSearchTerm, searchTerm]);
512:
513:    const hasActiveSearch = debouncedSearchTerm !== '' || isGlobalSearchActive;
514:
515:    // The Called Team pin is hidden under DMs (it's a group), and under Unread
516:    // only when there's nothing unread to surface. Suppressed during search so
517:    // results stay focused.
518:    const showCalledTeamSection = !isCustomerSuccessStaff
519:        && !hasActiveSearch
