export const ContactList = () => {
    const [channelList, setChannelList] = useState<GroupChannel[]>([]);
    const [listLoading, setListLoading] = useState(true);
    const { channelUrl } = useParams();
    const sendbirdState = useSendbirdStateContext();
    const sb = sendbirdState.stores.sdkStore.sdk as SendbirdGroupChat;
    const [, setLocation] = useTransitionLocation();
    const [searchTerm, setSearchTerm] = useState('');
    const [debouncedSearchTerm] = useDebounce(searchTerm, 300);
    const [pinnedChannels, setPinnedChannels] = useState<string[]>([]);
    const { data: profileSettings } = useGetSettings({});
    const [isInitialized, setIsInitialized] = useState(false);
    const { mutate: patchSettings } = usePatchSettings();
    const { isMobile } = useResponsive();
    const [activeFilter, setActiveFilter] = useState<ChannelFilter>('all');
    const isCustomerSuccessStaff = useIsCustomerSuccessStaff();

    const handleFilterChange = useCallback((filter: ChannelFilter) => {
        if (filter !== activeFilter) {
            dismissInboxFilterSelection();
        }

        setActiveFilter(filter);
    }, [activeFilter]);

    const sortChannels = (channels: GroupChannel[], pinnedChannelsToSort: string[]) => {
        const pinnedChans = channels.filter(ch => pinnedChannelsToSort.includes(ch.url));
        const unpinnedChans = channels.filter(ch => !pinnedChannelsToSort.includes(ch.url));

        const sortedPinned = [...pinnedChans].sort((a, b) => {
            const aIndex = pinnedChannelsToSort.indexOf(a.url);
            const bIndex = pinnedChannelsToSort.indexOf(b.url);
            return aIndex - bIndex;
        });

        const sortedUnpinned = [...unpinnedChans].sort((a, b) => {
            const aTime = a.lastMessage?.createdAt || 0;
            const bTime = b.lastMessage?.createdAt || 0;
            return bTime - aTime;
        });

        return [...sortedPinned, ...sortedUnpinned];
    };

    useEffect(() => {
        if (sb.groupChannel && profileSettings) {
            // Set pinned channels first
            if (profileSettings.pinnedChannels) {
                const sortedChannels = [...profileSettings.pinnedChannels]
                    .sort((a, b) => a.order - b.order)
                    .map(pin => pin.channel);
                setPinnedChannels(sortedChannels);
            }

            setIsInitialized(true);
        }
    }, [profileSettings?.pinnedChannels, sb.groupChannel]);

    // Handle pinned channels changes
    useEffect(() => {
        // We check if initialized since we're getting pinned from our backend, and all the channels from sendbird, just want to reduce any race conditions
        // This also fires when we pin or unpin after load.
        if (isInitialized) {
            // Rearrange the current channel list to respect new pinned order
            setChannelList(prevChannels => {
                const sortedChannels = sortChannels(prevChannels, pinnedChannels);
                return sortedChannels;
            });
        }
    }, [pinnedChannels, isInitialized]);

    // This gets the top X channels and updates the list, this is mainly used for user activity
    // This is called on a timer, this is in order to update user status, etc.
    const refreshRecentChannels = useCallback(async () => {
        // If we're searching, don't refresh since it would override the search.
        if (!sb.groupChannel || debouncedSearchTerm !== '') {
            return;
        }

        try {
            const query = sb.groupChannel.createMyGroupChannelListQuery({
                limit: TOP_CHANNELS_LIMIT,
                includeEmpty: false,
                order: GroupChannelListOrder.LATEST_LAST_MESSAGE
            });

            const recentChannels = await query.next();

            // Update existing channels preserving pinned order
            setChannelList(prevChannels => {
                const recentChannelMap = new Map(recentChannels.map(ch => [ch.url, ch]));

                // First, update all existing channels with new data
                const updatedChannels = prevChannels.map(channel =>
                    recentChannelMap.get(channel.url) || channel
                );

                // Add any new channels that weren't in our list
                recentChannels.forEach(channel => {
                    if (!updatedChannels.some(ch => ch.url === channel.url)) {
                        updatedChannels.push(channel);
                    }
                });

                return sortChannels(updatedChannels, pinnedChannels);
            });
        } catch (error) {
            log.error('Error refreshing recent channels', error);
        }
    }, [sb.groupChannel, pinnedChannels, debouncedSearchTerm]);

    // This gets all the channels from sendbird, this is used for the initial load and the search.
    const getChannels = async (searchKeyword = '') => {
        if (!sb.groupChannel) {
            return [];
        }

        try {
            const query = sb.groupChannel.createMyGroupChannelListQuery({
                limit: 100, // 100 is the max limit for sendbird
                includeEmpty: true,
                order: GroupChannelListOrder.LATEST_LAST_MESSAGE,
                ...(searchKeyword && {
                    searchFilter: {
                        query: searchKeyword,
                        fields: [GroupChannelSearchField.CHANNEL_NAME, GroupChannelSearchField.MEMBER_NICKNAME],
                    }
                })
            });

            // Get all channels in one go
            const channels: GroupChannel[] = [];
            while (query.hasNext) {
                // eslint-disable-next-line no-await-in-loop
                const batch = await query.next();
                channels.push(...batch);
            }

            return channels;
        } catch (error) {
            log.error('Error fetching channels', error);
            return [];
        }
    };

    // CS channels never appear in the main list. Non-staff see them via
    // <CalledTeamSection> pinned above; staff reach them via the Customer
    // Support filter row.
    const mainChannelList = useMemo(
        () => channelList.filter(ch => !isCustomerSuccessChannel(ch)),
        [channelList]
    );

    // This selects the first channel in the list, used when we don't have a channelUrl.
    // Uses mainChannelList so staff don't auto-land in (and instantly read) the CS
    // channel — it's reachable only via the Customer Support filter. Non-staff
    // customers with only a CS channel still land there so they're not left
    // with no selection.
    const selectFirstChannel = () => {
        const firstChannel = mainChannelList[0]
            ?? (!isCustomerSuccessStaff ? channelList.find(ch => isCustomerSuccessChannel(ch)) : undefined);
        if (firstChannel) {
            setLocation(`/${calledChatRoutes.chat.route}/${firstChannel.url}`);
        }
    };

    async function fetchInitialData() {
        if (!isInitialized || !sb.groupChannel) {
            return;
        }

        setListLoading(true);
        try {
            const allChannels = await getChannels();
            const sortedChannels = sortChannels(allChannels, pinnedChannels);
            setChannelList(sortedChannels);
        } catch (error) {
            log.error('Error fetching initial channels', error);
        } finally {
            setListLoading(false);
        }
         
    }

    const refreshSendbird = useSendbirdConnectionStore((state) => state.refreshSendbird);

    usePullToRefreshAddHandler(refreshSendbird);

    // When there's no channelUrl, land on the first channel. Keyed on channelUrl
    // and channelList as well as listLoading so navigating to bare /chat, or a
    // list that populates on a later refresh, still selects a channel instead of
    // leaving the list mounted with nothing open. We wait for listLoading so a
    // re-fetch (e.g. reconnect) doesn't pick from a stale, retained list.
    useEffect(() => {
        if (!channelUrl && !listLoading) {
            selectFirstChannel();
        }
    }, [channelUrl, listLoading, channelList]);

    // Fetch once initialized
    useEffect(() => {
        if (isInitialized) {
            void fetchInitialData();
        }
    }, [isInitialized]);

    const removeChannelFromPinned = useCallback((channelToRemove: string) => {
        // Remove from local state
        setPinnedChannels(prev => prev.filter(url => url !== channelToRemove));

        // Update server settings
        void patchSettings({
            body: {
                pinnedChannels: profileSettings?.pinnedChannels?.filter(
                    pinnedChannel => pinnedChannel.channel !== channelToRemove
                ) || [],
            },
        });
    }, [profileSettings?.pinnedChannels, patchSettings]);

    useEffect(() => {
        if (!sb.groupChannel) {
            return () => {};
        }

        // Setup channel handler for real-time updates, this is called from the handlers below.
        const updateChannelList = (baseChannel: BaseChannel) => {
            const channel = baseChannel as GroupChannel;
            setChannelList(prevChannels => {
                // First update/add the changed channel
                const updatedChannels = prevChannels.map(ch =>
                    ch.url === channel.url ? channel : ch
                );

                // If channel wasn't in the list, add it
                if (!updatedChannels.some(ch => ch.url === channel.url)) {
                    updatedChannels.push(channel);
                }

                return sortChannels(updatedChannels, pinnedChannels);
            });
        };

        const channelHandler = new GroupChannelHandler({
            onMessageReceived: (channel) => {
                updateChannelList(channel);
            },
            onMessageUpdated: (channel) => {
                updateChannelList(channel);
            },
            onUnreadMemberStatusUpdated: (channel) => {
                updateChannelList(channel);
            },
            onChannelChanged: (channel) => {
                updateChannelList(channel);
            },
            onChannelDeleted: (deletedChannelUrl) => {
                // Remove from channel list
                setChannelList(prevChannels =>
                    prevChannels.filter(ch => ch.url !== deletedChannelUrl)
                );

                if (pinnedChannels.includes(deletedChannelUrl)) {
                    removeChannelFromPinned(deletedChannelUrl);
                }

                void refreshRecentChannels();
            },
            onUserJoined: (baseChannel, user) => {
                const channel = baseChannel as GroupChannel;
                if (user.userId === sb.currentUser?.userId) {
                    setChannelList(prevChannels => {
                        // Check if this channel already existed in our list
                        const joinChannelExists = prevChannels.some(ch => ch.url === channel.url);

                        if (!joinChannelExists) {
                            // Only reorder for new channels
                            const lastPinnedIndex = pinnedChannels.length > 0
                                ? prevChannels.findIndex(ch => ch.url === pinnedChannels[pinnedChannels.length - 1])
                                : -1;

                            return [
                                ...prevChannels.slice(0, lastPinnedIndex + 1),
                                channel,
                                ...prevChannels.slice(lastPinnedIndex + 1)
                            ];
                        }

                        // For existing channels, just update the channel data in place
                        return prevChannels.map(ch =>
                            ch.url === channel.url ? channel : ch
                        );
                    });
                }
                // refresh the recent channels
                void refreshRecentChannels();
            },
            onUserLeft: (baseChannel, user) => {
                const channel = baseChannel as GroupChannel;

                // onUserLeft fires for EVERY remaining member when anyone leaves, so
                // only touch our own list/pins/selection when WE are the one who left.
                // Otherwise one member leaving would unpin the channel for everyone else.
                if (user.userId === sb.currentUser?.userId) {
                    setChannelList(prevChannels =>
                        prevChannels.filter(ch => ch.url !== channel.url)
                    );

                    if (pinnedChannels.includes(channel.url)) {
                        removeChannelFromPinned(channel.url);
                    }

                    // If we left the channel and had it selected, select the first channel
                    if (channel.url === channelUrl) {
                        selectFirstChannel();
                    }
                }

                void refreshRecentChannels();
            },

        });

        sb.groupChannel.addGroupChannelHandler('ContactListHandler', channelHandler);

        return () => {
            sb.groupChannel.removeGroupChannelHandler('ContactListHandler');
        };
    }, [sb.groupChannel, pinnedChannels]);

    // If the URL points at a channel that isn't in our local list yet
    // (e.g. just-created DM where the Sendbird onUserJoined event hasn't
    // landed), fetch it directly from Sendbird and add it instead of
    // bouncing the user to the first channel.
    useEffect(() => {
        if (!channelUrl || channelUrl.includes('new') || listLoading) {
            return undefined;
        }

        if (channelList.some(channel => channel.url === channelUrl)) {
            return undefined;
        }

        let cancelled = false;

        void (async () => {
            try {
                const channel = await sb.groupChannel.getChannel(channelUrl);
                if (cancelled || !channel || channel.url !== channelUrl) {
                    return;
                }
                setChannelList(prev => {
                    if (prev.some(ch => ch.url === channel.url)) {
                        return prev;
                    }
                    return sortChannels([...prev, channel], pinnedChannels);
                });
            } catch {
                if (!cancelled) {
                    // The remembered channel no longer resolves (deleted, or the
                    // user left it), so forget it before falling back — otherwise
                    // Chat would keep aiming at the dead url on every visit.
                    const { lastVisitedChannelUrl, setLastVisitedChannelUrl } = useLastVisitedChannelStore.getState();
                    if (channelUrl === lastVisitedChannelUrl) {
                        setLastVisitedChannelUrl(null);
                    }
                    selectFirstChannel();
                }
            }
        })();

        return () => {
            cancelled = true;
        };
    }, [channelUrl, channelList, listLoading]);

    // Remember the last channel the user actually landed on so the "Chat" nav
    // button can bring them back here. We only persist a channel that's in the
    // list, which guarantees it's real and viewable (DMs included) and excludes
    // placeholders like 'undefined'/'new' or channels the user has left. Read
    // via getState() so writing doesn't re-render this list on every refresh.
    useEffect(() => {
        if (!channelUrl || !channelList.some(channel => channel.url === channelUrl)) {
            return;
        }

        const { lastVisitedChannelUrl, setLastVisitedChannelUrl } = useLastVisitedChannelStore.getState();
        if (channelUrl !== lastVisitedChannelUrl) {
            setLastVisitedChannelUrl(channelUrl);
        }
    }, [channelUrl, channelList]);

    const handleSearch = (term: string) => {
        setSearchTerm(term);
    };

    // Refresh channels at an interval, this is used to update the unread count and other things
    useEffect(() => {
        void refreshRecentChannels();
        const intervalId = setInterval(() => {
            void refreshRecentChannels();
        }, REFRESH_INTERVAL);

        return () => clearInterval(intervalId);
    }, [refreshRecentChannels]);

    const customerSupportUnreadCount = useMemo(
        () => channelList
            .filter((ch) => isCustomerSuccessChannel(ch))
            .reduce((sum, ch) => sum + ch.unreadMessageCount, 0),
        [channelList]
    );

    // Staff only see the Customer Support filter when they're actually a member
    // of at least one CS channel. Domain alone isn't enough — most @called.app
    // accounts aren't on any CS channel and shouldn't see the row.
    const hasCustomerSupportChannels = useMemo(
        () => channelList.some((ch) => isCustomerSuccessChannel(ch)),
        [channelList]
    );

    const customerSuccessChannels = useMemo(
        () => (isCustomerSuccessStaff ? [] : channelList.filter(ch => isCustomerSuccessChannel(ch))),
        [channelList, isCustomerSuccessStaff]
    );

    // CS unread is counted toward the main Unread badge for customers (since
    // they see the Called Team section inline with their list), and excluded
    // for staff (who have a dedicated Customer Support filter with its own count).
    const totalUnreadCount = useMemo(() => {
        const mainCount = mainChannelList.reduce((sum, ch) => sum + ch.unreadMessageCount, 0);
        return isCustomerSuccessStaff ? mainCount : mainCount + customerSupportUnreadCount;
    }, [mainChannelList, customerSupportUnreadCount, isCustomerSuccessStaff]);

    const filteredChannelList = useMemo(
        () => (activeFilter === 'customer_support'
            ? filterChannels(channelList, 'customer_support')
            : filterChannels(mainChannelList, activeFilter)),
        [channelList, mainChannelList, activeFilter]
    );

    const setSharedChannelList = useChannelListStore((state) => state.setChannelList);
    useEffect(() => {
        setSharedChannelList(channelList);
    }, [channelList, setSharedChannelList]);

    const currentUserId = sb.currentUser?.userId ?? '';
    const searchFilteredChannels = useMemo(() => {
        if (!searchTerm) {
            return filteredChannelList;
        }
        const lowerTerm = searchTerm.toLowerCase();
        return filteredChannelList.filter((channel) =>
            getChannelName(channel, currentUserId).toLowerCase().includes(lowerTerm)
        );
    }, [filteredChannelList, searchTerm, currentUserId]);

    const filteredPinnedChannels = useMemo(
        () => pinnedChannels.filter(url => searchFilteredChannels.some(ch => ch.url === url)),
        [pinnedChannels, searchFilteredChannels]
    );

    const { searchTerm: globalSearchTerm, isSearchActive: isGlobalSearchActive } = useGlobalSearchStore((state) => ({
        searchTerm: state.searchTerm,
        isSearchActive: state.isSearchActive,
    }));

    // Sync local input when global store is cleared (e.g. clicking a search result)
    useEffect(() => {
        if (globalSearchTerm === '' && searchTerm !== '') {
            setSearchTerm('');
        }
    }, [globalSearchTerm, searchTerm]);

    const hasActiveSearch = debouncedSearchTerm !== '' || isGlobalSearchActive;

    // The Called Team pin is hidden under DMs (it's a group), and under Unread
    // only when there's nothing unread to surface. Suppressed during search so
    // results stay focused.
    const showCalledTeamSection = !isCustomerSuccessStaff
        && !hasActiveSearch
        && customerSuccessChannels.length > 0
        && activeFilter !== 'dms'
        && (activeFilter !== 'unread' || customerSupportUnreadCount > 0);

    // This handles the logic of the loading states with and without a search.
    const renderResults = () => {
        if (activeFilter === 'news' && !hasActiveSearch) {
            return <NewsInbox />;
        }

        if (activeFilter === 'prayers' && !hasActiveSearch) {
            return <PrayersInbox />;
        }

        if (listLoading && !searchTerm) {
            return <ContactListLoading />;
        }

        if (searchTerm && searchFilteredChannels.length === 0) {
            return (
                <div className="contact_list__no-results">
                    <p>No channels found matching {searchTerm}</p>
                </div>
            );
        }

        if (filteredChannelList.length === 0 && activeFilter !== 'all' && !showCalledTeamSection) {
            return (
                <div className="contact_list__no-results">
                    <p>{getEmptyFilterMessage(activeFilter)}</p>
                </div>
            );
        }

        return <ChannelList
            channels={searchFilteredChannels}
            pinnedChannels={filteredPinnedChannels}
            isSearchActive={hasActiveSearch} />;
    };

    return (
        <>
            <ContactHeader
                searchTerm={searchTerm}
                onSearchChange={handleSearch}
                onFilterChange={handleFilterChange}
                activeFilter={activeFilter}
                unreadCount={totalUnreadCount}
                customerSupportUnreadCount={customerSupportUnreadCount}
                hasCustomerSupportChannels={hasCustomerSupportChannels} />
            {!(isMobile && hasActiveSearch) && (
                <div className="contact_list__wrapper" data-clarity-mask="true">
                    <div className="contact_list__content">
                        {showCalledTeamSection && <CalledTeamSection channels={customerSuccessChannels} />}
                        {!hasActiveSearch && filteredPinnedChannels.length > 0 && !listLoading && (
                            <div className='contact_list__section_heading contact_list__all_chats_heading'>
                                <span className='contact_list__pinned'><PushPin size={16} /> PINNED</span>
                            </div>
                        )}
                        {renderResults()}
                    </div>
                </div>
            )}
        </>
    );
};

