import { useEffect, useState, memo } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { DoorOpen, EnvelopeSimple, Link, PushPin, Trash, UserPlus, Users } from '@phosphor-icons/react';
import Menu from '@mui/material/Menu';
import MenuItem from '@mui/material/MenuItem';
import type { GroupChannel } from '@sendbird/chat/groupChannel';
import { ConfirmationDialog } from 'called-common/src/components/ConfirmationDialog';
import { useDeleteChannel, useGetEntities, useGetSettings, useLeaveChannel, useLeaveEntity, usePatchSettings } from 'called-api/src/openApi/calledApiComponents';
import type { ChannelSchema, EntitySchema } from 'called-api/src/openApi/calledApiSchemas';
import { useChannelsList } from '@/hooks/useChannelsList';
import { useCopyInviteLink } from '@/hooks/useCopyInviteLink';
import { useIsCustomerSuccessStaff } from '@/hooks/useIsCustomerSuccessStaff';
import { useModalStore } from '@/stores/ModalStore';
import { isCustomerSuccessChannel } from '@/utils/channel';
import { hasLeaderOrAdminPermission } from '@/utils/user';
import localization from '@/localization/en.json';
import { ChannelMembersModal } from './ChannelMembersModal';
import { AddChannelMembersModal } from './AddChannelMembersModal';
import { MuteChannel } from './ChannelOptions/MuteChannel';

const CUSTOMER_SUPPORT_DELETE_AGE_MS = 30 * 24 * 60 * 60 * 1000;

interface LeavePermissions {
    canLeaveApiChannel: boolean;
    canLeaveChannel: boolean;
    canLeaveCustomerSupportChat: boolean;
}

const canDeleteChannel = (
    channel: GroupChannel,
    communityEntity: EntitySchema | null | undefined,
    isCustomerSupportChat: boolean,
    isPublicChannel: boolean
): boolean => {
    if (!isPublicChannel || !communityEntity || !hasLeaderOrAdminPermission(communityEntity)) {
        return false;
    }

    if (!isCustomerSupportChat) {
        return true;
    }

    return channel.createdAt > 0
        && Date.now() - channel.createdAt >= CUSTOMER_SUPPORT_DELETE_AGE_MS;
};

const canAddChannelMembers = (
    channelData: ChannelSchema | undefined,
    communityEntity: EntitySchema | null | undefined
): boolean => {
    const isNewEntityChannel = channelData?.type === 'ENTITY_PUBLIC' || channelData?.type === 'ENTITY_PRIVATE';
    return !!isNewEntityChannel && !!communityEntity && hasLeaderOrAdminPermission(communityEntity);
};

const getLeavePermissions = (
    channelData: ChannelSchema | undefined,
    communityEntity: EntitySchema | null | undefined,
    entity: EntitySchema | undefined,
    isChannelsListLoaded: boolean,
    isCustomerSupportChat: boolean,
    isCustomerSuccessStaff: boolean,
    isDirectMessage: boolean
): LeavePermissions => {
    const isPublicChannel = !entity;
    const isLeaderOrAdmin = !!communityEntity && hasLeaderOrAdminPermission(communityEntity);
    const canLeavePublicChannel = isPublicChannel && channelData?.type === 'ENTITY_PUBLIC';
    const canLeavePrivateChannel = isPublicChannel && channelData?.type === 'ENTITY_PRIVATE' && !isLeaderOrAdmin;
    const canLeaveEntityChannel = canLeavePublicChannel || canLeavePrivateChannel;
    // Wait for the channels query so a still-loading (or failed) list is never
    // mistaken for "no backend record", which would leave via Sendbird only and
    // strand the backend membership.
    const canLeaveCustomerSupportChat = isChannelsListLoaded && isCustomerSupportChat && isCustomerSuccessStaff;
    const canLeaveApiChannel = canLeaveEntityChannel || canLeaveCustomerSupportChat;

    return {
        canLeaveApiChannel,
        canLeaveChannel: isDirectMessage || entity?.affiliation?.role === 'MEMBER' || canLeaveApiChannel,
        canLeaveCustomerSupportChat,
    };
};

const getLeaveTitle = (
    canLeaveApiChannel: boolean,
    canLeaveCustomerSupportChat: boolean,
    groupType: string,
    isDirectMessage: boolean
): string => {
    if (isDirectMessage) {
        return localization.chat.chatOptions.leaveChat.leaveDirectMessage;
    }
    if (canLeaveCustomerSupportChat) {
        return 'Leave Customer Support Chat';
    }
    if (canLeaveApiChannel) {
        return 'Leave Channel';
    }
    return `Leave ${groupType}`;
};

const getLeaveDescription = (
    canLeaveApiChannel: boolean,
    channel: GroupChannel,
    entity: EntitySchema | undefined,
    isDirectMessage: boolean
): string => {
    if (isDirectMessage) {
        return localization.chat.chatOptions.leaveChat.confirmationDialog.description;
    }
    if (canLeaveApiChannel) {
        return `Are you sure you want to leave ${channel.name || 'this channel'}?`;
    }
    return `Are you sure you want to leave ${entity?.name}?`;
};

