        &:hover {
            background-color: var(--bg-strong);
        }
    }

    &__avatar_container {
        position: relative;
        flex-shrink: 0;
        width: 40px;
        height: 40px;
    }

    &__mute_icon {
        display: flex;
        position: absolute;
        right: -2px;
        bottom: -2px;
        align-items: center;
        justify-content: center;
        width: 16px;
        height: 16px;
        border: 1px solid var(--border-default);
        border-radius: 50%;
        background-color: var(--bg-default);
        color: var(--text-default);
    }

    &__content {
        display: flex;
        flex: 1;
        flex-direction: column;
        min-width: 0;
        gap: 2px;
    }

    &__row_top {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 8px;
    }

    &__name_row {
        display: flex;
        align-items: center;
        min-width: 0;
        gap: 4px;
    }

    &__name {
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;

        &__unread {
            font: var(--web-base-semibold);
        }
    }

    &__timestamp {
        flex-shrink: 0;
        color: var(--text-weak);
        font: var(--web-xs-medium);
    }

    &__row_bottom {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 8px;
    }

    &__preview {
        flex: 1;
        min-width: 0;
        overflow: hidden;
        color: var(--text-medium);
        font: var(--web-sm-medium);
        text-overflow: ellipsis;
        white-space: nowrap;

        &__muted {
            opacity: 0.6;
        }
    }

    &__sender {
        color: var(--text-medium);
    }

    &__notification_container {
        display: flex;
        flex-shrink: 0;
        align-items: center;
        justify-content: center;
        min-width: 20px;
    }

    &__notifications {
        display: flex;
        align-items: center;
        justify-content: center;
        width: 20px;
        height: 16px;
        padding: 3px 0;
        border-radius: 50%;
        background-color: var(--brand);
        color: var(--icon-inverted-default);
        font: var(--web-2xs-semibold);
    }

    &__pip {
        width: 12px;
        height: 12px;
        border: 2px solid var(--border-weak);
        border-radius: 50%;
        background-color: var(--brand);
        color: var(--icon-inverted-default);
    }

    &.muted {
        .contact__name {
            color: var(--text-medium);
        }
    }
}

@media (width >= $md) {
    .selected {
        background-color: var(--bg-strong);
    }
}

