import type { GroupChannel } from '@sendbird/chat/groupChannel';
import { ChannelSchema } from 'called-api/src/openApi/calledApiSchemas';

export const CUSTOMER_SUCCESS_CHANNEL_TYPE = 'CUSTOMER_SUCCESS';
export const CUSTOMER_SUCCESS_CUSTOMER_DISPLAY_NAME = 'Called Team';

export const isCustomerSuccessChannel = (channel: GroupChannel) =>
    channel.customType === CUSTOMER_SUCCESS_CHANNEL_TYPE;

const getChannelType = (channel: GroupChannel): ChannelSchema['type'] => {
    if (channel.customType === 'User' || !channel.name || channel.name === 'Group Channel') {
        return 'DM';
    }

    return 'ENTITY';
};

export const isDirectMessage = (channel: GroupChannel) => getChannelType(channel) === 'DM';

export const getChannelName = (channel: GroupChannel, currentUserId: string) => {
    const { name, members } = channel;

    // "Group Channel" is the Sendbird placeholder
    if (!isDirectMessage(channel) && name && name !== 'Group Channel') {
        return name;
    }

    if (members.length === 1) {
        const currentUser = members.find((member) => member.userId === currentUserId);
        return `${currentUser?.nickname} (you)`;
    }

    return members
        .filter((member) => member.userId !== currentUserId)
        .map((member) => member.nickname)
        .join(', ')
        .trim();
};

export type ChannelFilter = 'all' | 'dms' | 'groups' | 'unread' | 'customer_support' | 'news' | 'prayers';

export const CUSTOMER_SUPPORT_FILTER_LABEL = 'Customer Support';

export const CHANNEL_FILTERS: { key: ChannelFilter; label: string }[] = [
    { key: 'all', label: 'All' },
    { key: 'dms', label: 'DMs' },
    { key: 'groups', label: 'Groups' },
    { key: 'unread', label: 'Unread' },
];

export const CHAT_HOME_CHANNEL_FILTERS: { key: ChannelFilter; label: string }[] = [
    { key: 'all', label: 'All' },
    { key: 'prayers', label: 'Prayers' },
    { key: 'news', label: 'News' },
    { key: 'unread', label: 'Unread' },
];

export const getChannelFilters = (chatHome: boolean) => (
    chatHome ? CHAT_HOME_CHANNEL_FILTERS : CHANNEL_FILTERS
);

export const filterChannels = (channels: GroupChannel[], filter: ChannelFilter): GroupChannel[] => {
    switch (filter) {
        case 'dms':
            return channels.filter((ch) => isDirectMessage(ch));
        case 'groups':
            return channels.filter((ch) => !isDirectMessage(ch));
        case 'unread':
            return channels.filter((ch) => ch.unreadMessageCount > 0);
        case 'customer_support':
            return channels.filter((ch) => isCustomerSuccessChannel(ch));
        case 'news':
        case 'prayers':
            return [];
        default:
            return channels;
    }
};

export const getEmptyFilterMessage = (filter: ChannelFilter): string => {
    switch (filter) {
        case 'dms':
            return 'No direct messages';
        case 'groups':
            return 'No group channels';
        case 'unread':
            return 'No unread messages';
        case 'customer_support':
            return 'No customer support channels';
        case 'news':
            return 'No news';
        case 'prayers':
            return 'No prayers';
        default:
            return 'No channels';
    }
};

